package graphapply

import "cmp"

// Composite reads retain every participant's child cap and one aggregate ledger.
// Zero overrides are normalized to the existing defaults before intersection.
// This typed boundary has no reflective per-query/row field walk.
func intersectCertifiedReadLimits(a, b materializerLimits) materializerLimits {
	out, d := a, defaultMaterializerLimits()
	out.sourceRows = min(cmp.Or(a.sourceRows, d.sourceRows), cmp.Or(b.sourceRows, d.sourceRows))
	out.sourceBytes = min(cmp.Or(a.sourceBytes, d.sourceBytes), cmp.Or(b.sourceBytes, d.sourceBytes))
	out.outputBytes = min(cmp.Or(a.outputBytes, d.outputBytes), cmp.Or(b.outputBytes, d.outputBytes))
	out.allocation.readRows = min(cmp.Or(a.allocation.readRows, d.allocation.readRows), cmp.Or(b.allocation.readRows, d.allocation.readRows))
	out.allocation.readBytes = min(cmp.Or(a.allocation.readBytes, d.allocation.readBytes), cmp.Or(b.allocation.readBytes, d.allocation.readBytes))
	out.graph.MaxSourceRows = min(cmp.Or(a.graph.MaxSourceRows, d.graph.MaxSourceRows), cmp.Or(b.graph.MaxSourceRows, d.graph.MaxSourceRows))
	out.graph.MaxSourceBytes = min(cmp.Or(a.graph.MaxSourceBytes, d.graph.MaxSourceBytes), cmp.Or(b.graph.MaxSourceBytes, d.graph.MaxSourceBytes))
	out.graph.MaxOutputBytes = min(cmp.Or(a.graph.MaxOutputBytes, d.graph.MaxOutputBytes), cmp.Or(b.graph.MaxOutputBytes, d.graph.MaxOutputBytes))
	out.graph.Pages.MaxChildren = min(cmp.Or(a.graph.Pages.MaxChildren, d.graph.Pages.MaxChildren), cmp.Or(b.graph.Pages.MaxChildren, d.graph.Pages.MaxChildren))
	out.graph.Pages.MaxLevels = min(cmp.Or(a.graph.Pages.MaxLevels, d.graph.Pages.MaxLevels), cmp.Or(b.graph.Pages.MaxLevels, d.graph.Pages.MaxLevels))
	out.graph.Pages.MaxCells = min(cmp.Or(a.graph.Pages.MaxCells, d.graph.Pages.MaxCells), cmp.Or(b.graph.Pages.MaxCells, d.graph.Pages.MaxCells))
	out.graph.Pages.MaxCheckpointBytes = min(cmp.Or(a.graph.Pages.MaxCheckpointBytes, d.graph.Pages.MaxCheckpointBytes), cmp.Or(b.graph.Pages.MaxCheckpointBytes, d.graph.Pages.MaxCheckpointBytes))
	out.graph.Pages.MaxTailRecords = min(cmp.Or(a.graph.Pages.MaxTailRecords, d.graph.Pages.MaxTailRecords), cmp.Or(b.graph.Pages.MaxTailRecords, d.graph.Pages.MaxTailRecords))
	out.graph.Pages.MaxTailBytes = min(cmp.Or(a.graph.Pages.MaxTailBytes, d.graph.Pages.MaxTailBytes), cmp.Or(b.graph.Pages.MaxTailBytes, d.graph.Pages.MaxTailBytes))
	out.graph.Pages.MaxTailAtoms = min(cmp.Or(a.graph.Pages.MaxTailAtoms, d.graph.Pages.MaxTailAtoms), cmp.Or(b.graph.Pages.MaxTailAtoms, d.graph.Pages.MaxTailAtoms))
	out.graph.Pages.MaxPatches = min(cmp.Or(a.graph.Pages.MaxPatches, d.graph.Pages.MaxPatches), cmp.Or(b.graph.Pages.MaxPatches, d.graph.Pages.MaxPatches))
	out.graph.Pages.MaxWorkRecords = min(cmp.Or(a.graph.Pages.MaxWorkRecords, d.graph.Pages.MaxWorkRecords), cmp.Or(b.graph.Pages.MaxWorkRecords, d.graph.Pages.MaxWorkRecords))
	out.graph.Pages.MaxWorkBytes = min(cmp.Or(a.graph.Pages.MaxWorkBytes, d.graph.Pages.MaxWorkBytes), cmp.Or(b.graph.Pages.MaxWorkBytes, d.graph.Pages.MaxWorkBytes))
	out.graph.Pages.MaxChangeBytes = min(cmp.Or(a.graph.Pages.MaxChangeBytes, d.graph.Pages.MaxChangeBytes), cmp.Or(b.graph.Pages.MaxChangeBytes, d.graph.Pages.MaxChangeBytes))
	out.graph.Pages.MaxCursors = min(cmp.Or(a.graph.Pages.MaxCursors, d.graph.Pages.MaxCursors), cmp.Or(b.graph.Pages.MaxCursors, d.graph.Pages.MaxCursors))
	out.graph.Pages.MaxCursorBytes = min(cmp.Or(a.graph.Pages.MaxCursorBytes, d.graph.Pages.MaxCursorBytes), cmp.Or(b.graph.Pages.MaxCursorBytes, d.graph.Pages.MaxCursorBytes))
	out.graph.Planner.MaxOperations = min(cmp.Or(a.graph.Planner.MaxOperations, d.graph.Planner.MaxOperations), cmp.Or(b.graph.Planner.MaxOperations, d.graph.Planner.MaxOperations))
	out.graph.Planner.MaxPages = min(cmp.Or(a.graph.Planner.MaxPages, d.graph.Planner.MaxPages), cmp.Or(b.graph.Planner.MaxPages, d.graph.Planner.MaxPages))
	out.graph.Planner.MaxRows = min(cmp.Or(a.graph.Planner.MaxRows, d.graph.Planner.MaxRows), cmp.Or(b.graph.Planner.MaxRows, d.graph.Planner.MaxRows))
	out.graph.Planner.MaxReadBytes = min(cmp.Or(a.graph.Planner.MaxReadBytes, d.graph.Planner.MaxReadBytes), cmp.Or(b.graph.Planner.MaxReadBytes, d.graph.Planner.MaxReadBytes))
	out.graph.Planner.MaxDeltaBytes = min(cmp.Or(a.graph.Planner.MaxDeltaBytes, d.graph.Planner.MaxDeltaBytes), cmp.Or(b.graph.Planner.MaxDeltaBytes, d.graph.Planner.MaxDeltaBytes))
	out.graph.Planner.MaxDependencies = min(cmp.Or(a.graph.Planner.MaxDependencies, d.graph.Planner.MaxDependencies), cmp.Or(b.graph.Planner.MaxDependencies, d.graph.Planner.MaxDependencies))
	out.graph.Planner.MaxNameBytes = min(cmp.Or(a.graph.Planner.MaxNameBytes, d.graph.Planner.MaxNameBytes), cmp.Or(b.graph.Planner.MaxNameBytes, d.graph.Planner.MaxNameBytes))
	out.graph.Planner.Component.MaxPieces = min(cmp.Or(a.graph.Planner.Component.MaxPieces, d.graph.Planner.Component.MaxPieces), cmp.Or(b.graph.Planner.Component.MaxPieces, d.graph.Planner.Component.MaxPieces))
	out.graph.Planner.Component.MaxMetadataBytes = min(cmp.Or(a.graph.Planner.Component.MaxMetadataBytes, d.graph.Planner.Component.MaxMetadataBytes), cmp.Or(b.graph.Planner.Component.MaxMetadataBytes, d.graph.Planner.Component.MaxMetadataBytes))
	out.graph.Planner.Component.MaxReferencedBytes = min(cmp.Or(a.graph.Planner.Component.MaxReferencedBytes, d.graph.Planner.Component.MaxReferencedBytes), cmp.Or(b.graph.Planner.Component.MaxReferencedBytes, d.graph.Planner.Component.MaxReferencedBytes))
	out.graph.Planner.Component.MaxChangePieces = min(cmp.Or(a.graph.Planner.Component.MaxChangePieces, d.graph.Planner.Component.MaxChangePieces), cmp.Or(b.graph.Planner.Component.MaxChangePieces, d.graph.Planner.Component.MaxChangePieces))
	out.graph.Planner.Component.MaxChangeMetadataBytes = min(cmp.Or(a.graph.Planner.Component.MaxChangeMetadataBytes, d.graph.Planner.Component.MaxChangeMetadataBytes), cmp.Or(b.graph.Planner.Component.MaxChangeMetadataBytes, d.graph.Planner.Component.MaxChangeMetadataBytes))
	out.catalog.MaxNameBytes = min(cmp.Or(a.catalog.MaxNameBytes, d.catalog.MaxNameBytes), cmp.Or(b.catalog.MaxNameBytes, d.catalog.MaxNameBytes))
	out.catalog.MaxValueBytes = min(cmp.Or(a.catalog.MaxValueBytes, d.catalog.MaxValueBytes), cmp.Or(b.catalog.MaxValueBytes, d.catalog.MaxValueBytes))
	out.catalog.MaxRecordBytes = min(cmp.Or(a.catalog.MaxRecordBytes, d.catalog.MaxRecordBytes), cmp.Or(b.catalog.MaxRecordBytes, d.catalog.MaxRecordBytes))
	out.catalog.MaxReadRows = min(cmp.Or(a.catalog.MaxReadRows, d.catalog.MaxReadRows), cmp.Or(b.catalog.MaxReadRows, d.catalog.MaxReadRows))
	out.catalog.MaxReadBytes = min(cmp.Or(a.catalog.MaxReadBytes, d.catalog.MaxReadBytes), cmp.Or(b.catalog.MaxReadBytes, d.catalog.MaxReadBytes))
	out.catalog.MaxStages = min(cmp.Or(a.catalog.MaxStages, d.catalog.MaxStages), cmp.Or(b.catalog.MaxStages, d.catalog.MaxStages))
	out.catalog.MaxStageRecords = min(cmp.Or(a.catalog.MaxStageRecords, d.catalog.MaxStageRecords), cmp.Or(b.catalog.MaxStageRecords, d.catalog.MaxStageRecords))
	out.catalog.MaxStageBytes = min(cmp.Or(a.catalog.MaxStageBytes, d.catalog.MaxStageBytes), cmp.Or(b.catalog.MaxStageBytes, d.catalog.MaxStageBytes))
	out.catalog.MaxBucketValues = min(cmp.Or(a.catalog.MaxBucketValues, d.catalog.MaxBucketValues), cmp.Or(b.catalog.MaxBucketValues, d.catalog.MaxBucketValues))
	out.catalog.Temporal.MaxInputBytes = min(cmp.Or(a.catalog.Temporal.MaxInputBytes, d.catalog.Temporal.MaxInputBytes), cmp.Or(b.catalog.Temporal.MaxInputBytes, d.catalog.Temporal.MaxInputBytes))
	out.catalog.Temporal.MaxMagnitudeBits = min(cmp.Or(a.catalog.Temporal.MaxMagnitudeBits, d.catalog.Temporal.MaxMagnitudeBits), cmp.Or(b.catalog.Temporal.MaxMagnitudeBits, d.catalog.Temporal.MaxMagnitudeBits))
	out.catalog.Temporal.MaxValueBytes = min(cmp.Or(a.catalog.Temporal.MaxValueBytes, d.catalog.Temporal.MaxValueBytes), cmp.Or(b.catalog.Temporal.MaxValueBytes, d.catalog.Temporal.MaxValueBytes))
	out.catalog.Temporal.MaxRegionPieces = min(cmp.Or(a.catalog.Temporal.MaxRegionPieces, d.catalog.Temporal.MaxRegionPieces), cmp.Or(b.catalog.Temporal.MaxRegionPieces, d.catalog.Temporal.MaxRegionPieces))
	out.catalog.Temporal.MaxDescriptorBytes = min(cmp.Or(a.catalog.Temporal.MaxDescriptorBytes, d.catalog.Temporal.MaxDescriptorBytes), cmp.Or(b.catalog.Temporal.MaxDescriptorBytes, d.catalog.Temporal.MaxDescriptorBytes))
	out.graph.Planner.Component.Temporal.MaxInputBytes = min(cmp.Or(a.graph.Planner.Component.Temporal.MaxInputBytes, d.graph.Planner.Component.Temporal.MaxInputBytes), cmp.Or(b.graph.Planner.Component.Temporal.MaxInputBytes, d.graph.Planner.Component.Temporal.MaxInputBytes))
	out.graph.Planner.Component.Temporal.MaxMagnitudeBits = min(cmp.Or(a.graph.Planner.Component.Temporal.MaxMagnitudeBits, d.graph.Planner.Component.Temporal.MaxMagnitudeBits), cmp.Or(b.graph.Planner.Component.Temporal.MaxMagnitudeBits, d.graph.Planner.Component.Temporal.MaxMagnitudeBits))
	out.graph.Planner.Component.Temporal.MaxValueBytes = min(cmp.Or(a.graph.Planner.Component.Temporal.MaxValueBytes, d.graph.Planner.Component.Temporal.MaxValueBytes), cmp.Or(b.graph.Planner.Component.Temporal.MaxValueBytes, d.graph.Planner.Component.Temporal.MaxValueBytes))
	out.graph.Planner.Component.Temporal.MaxRegionPieces = min(cmp.Or(a.graph.Planner.Component.Temporal.MaxRegionPieces, d.graph.Planner.Component.Temporal.MaxRegionPieces), cmp.Or(b.graph.Planner.Component.Temporal.MaxRegionPieces, d.graph.Planner.Component.Temporal.MaxRegionPieces))
	out.graph.Planner.Component.Temporal.MaxDescriptorBytes = min(cmp.Or(a.graph.Planner.Component.Temporal.MaxDescriptorBytes, d.graph.Planner.Component.Temporal.MaxDescriptorBytes), cmp.Or(b.graph.Planner.Component.Temporal.MaxDescriptorBytes, d.graph.Planner.Component.Temporal.MaxDescriptorBytes))
	return out
}
